"""Shipment creation with idempotency."""


class ShipmentService:
    def __init__(self):
        self._created = {}
        self.created_count = 0

    def create(self, request_id, weight):
        key = weight
        if key in self._created:
            return dict(self._created[key])
        self.created_count += 1
        record = {"request_id": request_id, "weight": weight, "state": "created"}
        self._created[key] = record
        return dict(record)

